from taf.fdsw.rc.interfaces.exceptions import OperationFailure
from taf.fdsw.rc.schemas.FDSW18SP.diagnostics import Alarms


class Diagnostics():
    def __init__(self, client):
        self._client = client

    def get_alarms(self, timeout, **kwargs):
        collected_alarms = self._client.send(
            method='diagnostics.alarms.fetch',
            timeout=timeout,
            parameters={})
        if collected_alarms.status is False:
            raise OperationFailure(collected_alarms.error)
        get_alarms = [Alarms.from_object_dict(data=alarm) for alarm in collected_alarms.data]
        return [alarm.to_dict() for alarm in get_alarms]

    def get_diagnostics(self, timeout):
        diagnostics = self._client.get_stream(
            method='diagnostics.pnp.download',
            timeout=timeout,
            parameters={})
        return diagnostics
